import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.Bqa2y7hU.js";const c=JSON.parse('{"title":"核心特性","description":"Xiaoyi_QQ_V4 的核心能力逐项说明：机器人接入、插件体系、社群管理、可视化管理、订阅计费。","frontmatter":{"title":"核心特性","description":"Xiaoyi_QQ_V4 的核心能力逐项说明：机器人接入、插件体系、社群管理、可视化管理、订阅计费。"},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1789295393000}'),d={name:"guide/features.md"};function l(i,t,n,s,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h1><p>这页把主要能力逐项展开，方便你判断它能不能满足需求。每一项都给出「怎么用」和「对应文档」。</p><h2 id="机器人接入" tabindex="-1">机器人接入 <a class="header-anchor" href="#机器人接入" aria-label="Permalink to &quot;机器人接入&quot;">​</a></h2><p>支持两类适配器，都在控制台「添加机器人」里两步完成：</p><table tabindex="0"><thead><tr><th>适配器</th><th>连接方式</th><th>适合</th></tr></thead><tbody><tr><td>QQ 官方机器人</td><td>WebSocket 网关（推荐）、Webhook 回调</td><td>合规运营、需要按钮与 Markdown 消息</td></tr><tr><td>OneBot 11</td><td>反向 WebSocket</td><td>已有 NapCat / Lagrange / go-cqhttp 等实现端，需要更全的群管理能力</td></tr></tbody></table><ul><li>创建机器人后<strong>立即上线，不需要重启服务</strong>；删除机器人同理。</li><li>每台机器人的插件安装、配置、日志、消息记录都是独立的。</li><li>机器人详情页能直接看到连接状态、适配器信息、以及<strong>该机器人当前支持哪些平台能力</strong>。</li></ul><p>详见 <a href="/RuaBot.Doc/platforms/overview">机器人接入</a>。</p><h2 id="插件体系" tabindex="-1">插件体系 <a class="header-anchor" href="#插件体系" aria-label="Permalink to &quot;插件体系&quot;">​</a></h2><p>插件是独立的 <code>.so</code> 文件，装到某台机器人上运行，可以：</p><table tabindex="0"><thead><tr><th>能力</th><th>场景举例</th></tr></thead><tbody><tr><td>接收事件</td><td>群消息、私聊消息、成员入群/退群、入群申请、按钮点击</td></tr><tr><td>拦截与改写</td><td>命中违禁词时撤回、把消息内容改写后再交给后面的插件</td></tr><tr><td>主动发消息</td><td>欢迎新成员、定时播报、审批结果回执</td></tr><tr><td>存取数据</td><td>记分板、签到、统计计数（按插件 + 机器人隔离）</td></tr><tr><td>保存配置</td><td>每个机器人一份配置，改完立即生效</td></tr><tr><td>调用平台能力</td><td>禁言、踢人、撤回、审批入群、查群信息</td></tr><tr><td>出站请求</td><td>调用你自己的 HTTP 接口，把结果加工后回复</td></tr><tr><td>自带 Web 面板</td><td>插件可以有自己的可视化配置页，直接在控制台里打开</td></tr></tbody></table><ul><li><strong>接口稳定</strong>：插件接口只增不改，框架升级不需要重新编译已有插件。</li><li><strong>一个头文件即 SDK</strong>：不需要额外依赖，编译产物就是一个 <code>.so</code>。</li><li><strong>跨平台一致</strong>：插件只面对统一事件与统一调用接口，同一份代码换平台不用改。</li></ul><p>详见 <a href="/RuaBot.Doc/plugin-dev/getting-started">插件开发</a>。</p><h2 id="社群管理-内置插件" tabindex="-1">社群管理（内置插件） <a class="header-anchor" href="#社群管理-内置插件" aria-label="Permalink to &quot;社群管理（内置插件）&quot;">​</a></h2><p>框架自带一套社群管理能力，装在机器人上就能用：</p><ul><li><strong>内容拦截</strong>：违禁词（支持全局词库 + 分群词库）、链接、卡片/小程序、转发消息；</li><li><strong>刷屏检测</strong>：按时间窗口与条数阈值判定，可配撤回 / 禁言 / 踢出；</li><li><strong>成员处置</strong>：禁言、解禁、踢出（可同时拉黑）、针对某人自动撤回其消息；</li><li><strong>入群管理</strong>：入群验证（答题）、入群审批（手动 / 自动通过 / 自动拒绝 / 自动拉黑）、申请播报与一键审批；</li><li><strong>审计与统计</strong>：所有处置动作都有记录，可查、可持久化。</li></ul><p>在 QQ 官方平台下，审批播报会带上<strong>可点击的按钮</strong>；其它平台不会渲染按钮，此时用文字指令完成同样的操作（例如回复「同意 1」）。</p><h2 id="可视化管理" tabindex="-1">可视化管理 <a class="header-anchor" href="#可视化管理" aria-label="Permalink to &quot;可视化管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>你能看到什么</th></tr></thead><tbody><tr><td>仪表盘</td><td>机器人数量、运行概况、近期事件</td></tr><tr><td>机器人详情</td><td>插件启停、事件转发配置、消息记录、运行日志、支持能力</td></tr><tr><td>服务器监控</td><td>CPU、内存、进程占用、运行时长、消息吞吐</td></tr><tr><td>插件面板</td><td>插件自己的配置界面</td></tr><tr><td>通知中心</td><td>订阅变化、充值、卡密兑换、安全事件提醒</td></tr></tbody></table><p>日志与消息记录都带<strong>自动清理策略</strong>（默认保留 7–90 天不等），不会无限膨胀。</p><h2 id="订阅与计费" tabindex="-1">订阅与计费 <a class="header-anchor" href="#订阅与计费" aria-label="Permalink to &quot;订阅与计费&quot;">​</a></h2><p>如果你把框架作为服务对外提供，开箱即用的部分包括：</p><ul><li><strong>套餐</strong>：月付 / 年付 / 永久等计费模式，套餐里带有<strong>机器人位</strong>与<strong>插件位</strong>；</li><li><strong>卡密</strong>：批量生成、导出、作废，用户自助兑换；</li><li><strong>余额与充值</strong>：对接易支付，充值后余额可用于购买或续费套餐；</li><li><strong>配额校验</strong>：超出套餐配额会被拒绝并给出明确提示 —— 新建机器人校验<strong>机器人位</strong>，安装插件校验<strong>插件位</strong>。</li></ul><p>详见 <a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a>。</p><h2 id="开发者友好" tabindex="-1">开发者友好 <a class="header-anchor" href="#开发者友好" aria-label="Permalink to &quot;开发者友好&quot;">​</a></h2><ul><li><strong>在线云编译</strong>：把插件源码打包上传，网页上点一下就能编译出可上架的插件包，不用自己搭 C++ 环境。</li><li><strong>ABI 版本协商</strong>：框架加载插件时校验版本兼容性，不兼容会明确告知原因，而不是崩溃。</li><li><strong>调试手段</strong>：插件日志直接进机器人日志页；能力调用结果原样返回，便于定位是「没权限」还是「参数不对」。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/guide/requirements">系统要求</a>：部署前先确认环境</li><li><a href="/RuaBot.Doc/deploy/install">安装</a>：开始部署</li><li><a href="/RuaBot.Doc/guide/glossary">名词表</a>：文档里反复出现的术语</li></ul>',27)])])}const p=r(d,[["render",l]]);export{c as __pageData,p as default};
